def nth_good_integer(N):
    def is_good_integer(num):
        while num > 0:
            if (num % 10) % 2 != 0:
                return False
            num //= 10
        return True

    count = 0
    current = 0
    while True:
        if is_good_integer(current):
            count += 1
            if count == N:
                return current
        current += 1
